 async function verifySelected(){if(!job||!chain)throw Error('select_job');const c=await configForJob(chain,job,trusted);if(!job.paymentSignature&&!job.reconciledSignature){const found=await findPaymentByReference(c,job.order);if(!found.signature){setInfo('Подтверждённая оплата не найдена. Это не доказывает отсутствие списания. Прежняя попытка сохранена; новый платёж не отправляется.');setResult(found);return;}job.reconciledSignature=found.signature;await saveJob(job);setJobs(await cachedJobs());}const verified=await reconcileJob(job,c,jobs);setPaymentChecks(old=>({...old,[job.order.id]:true}));setResult({status:'Solana finalized / платёж проверен через выбранный RPC',...verified,execution:'Архив ещё не считается сохранённым'});}
