 const wallet=arWallet();await wallet.connect(['ACCESS_ADDRESS','ACCESS_PUBLIC_KEY','SIGN_TRANSACTION']);const quote=await arQuote(c.arweaveNodes,c.wallets.arReserve,job.order.archive!.bytes);setResult(quote);
